		map = findMapLocationForMcpcinMethod((((usqInt)cogMethod)) + (sizeof(CogBlockMethod)), homeMethod);
		assert(map != 0);
		annotation = ((usqInt)((byteAt((void *)(map))))) >> AnnotationShift;
		assert((((annotation) >> AnnotationShift) == HasBytecodePC)
		 || (((annotation) >> AnnotationShift) == IsDisplacementX2N));

		/* fiducial */
		while (((annotation = ((usqInt)((byteAt((void *)(map))))) >> AnnotationShift)) != HasBytecodePC) {
			map -= 1;
		}

