	assert(mcpc < (freeStart()));
	cogMethod = ((CogMethod *) baseAddress);

	/* Speed up the search by finding the entry in the openPICList before mcpc.
	   Typically 2 to 3% of the zone's entities are openPICs. The openPICList is ordered high to low. */
	if (openPICList) {
		prevMethod = openPICList;
		while (!((!prevMethod)
		 || ((((usqInt)prevMethod)) < mcpc))) {
			prevMethod = ((CogMethod *) ((prevMethod->nextOpenPIC)));
		}
		if (prevMethod) {
			cogMethod = prevMethod;
		}
	}

	/* Now search upward from either baseAddress or the first entry in the openPICList below mcpc. */
	while ((((usqInt)cogMethod)) < mcpc) {
		prevMethod = cogMethod;
		cogMethod = ((CogMethod *) (roundUpToMethodAlignment(backEnd, (((usqInt)cogMethod)) + ((cogMethod->blockSize)))));
	}
	return prevMethod;
