	finished = (((usqInt)nonFwdJumpTargetOrZero)
				? nonFwdJumpTargetOrZero
				: genoperandoperand(Label, (labelCounter += 1), bytecodePC));
	jmpTarget(imm, jmpTarget(ok, finished));
