			routine = ceSmallActiveContextInMethodTrampoline;
			break;
		case InVanillaBlock:
			routine = ceSmallActiveContextInBlockTrampoline;
			break;
		case InFullBlock:
			routine = ceSmallActiveContextInFullBlockTrampoline;
