	/* PopR: */
	genoperand(PopR, RBX);

	/* PopR: */
	genoperand(PopR, RCX);

	/* PopR: */
	genoperand(PopR, RDX);

	/* RetN: */
	genoperand(RetN, 0);
	outputInstructionsForGeneratedRuntimeAt(startAddress);

