    sqInt oilBcpc;
    sqInt oilNumExtB;

	descriptor = ((OilBytecodeDescriptor *) 0);
	oilExtA = (oilExtB = (oilNumExtB = 0));
	oilByte1 = (oilByte2 = 0);
