	/* OilFullCompiler>>#fuseFloats */
static sqInt
fuseFloats(void)
{
    usqInt branchTarget;
    sqInt irOffset;
    sqInt offset;
    sqInt opcode;

	for (offset = 0; offset < irIndex; offset += 1) {
		oilIRFlag[offset] = 0;
		oilIRTarget[offset] = 0;
	}
	irOffset = 0;
	while (irOffset < irIndex) {
		opcode = opcodeAt(irOffset);
		if ((oilOpInfo[opcode]) & OilOpBranch) {
			branchTarget = imm16At(irOffset);
			oilIRTarget[branchTarget] = (((((oilIRTarget[branchTarget]) + 1) < 0xFF) ? ((oilIRTarget[branchTarget]) + 1) : 0xFF));
		}
		irOffset += instructionLengthAt(irOffset);
	}
	computeIRSites();
	irOffset = 0;
	while (irOffset < irIndex) {
		irOffset = (isFloatOpcode(opcodeAt(irOffset))
					? fuseFloatChainAt(irOffset)
					: irOffset + (instructionLengthAt(irOffset)));
	}
	return 0;
}


