    sqInt constant;
    AbstractInstruction *jmpTarget;

	if (boolReg == OilFlagsReg) {
		return abortCompilation(OilFailBackend);
	}

	/* flags are always consumed by genCompareAt:site: */
	boolMach = srcscratch(boolReg, TempReg);
