    usqInt cond;
    AbstractInstruction *jump;
    sqInt objMach;
    int onTrue;
    sqInt singleton;
    sqInt tag;
    usqInt target;

	cond = fieldAAt(irOffset);
	branchOffset = irOffset + (instructionLengthAt(irOffset));
