	quickConstant = word64AtBytecountofConstant(baseByte, count, constOop);

	/* begin CmpCq:R: */
	/* gen:quickConstant:operand: */
	/* checkQuickConstant:forInstruction: */
	genoperandoperand(CmpCqR, quickConstant, TempReg);
