		/* begin MoveMw:r:R: */
		/* gen:quickConstant:operand:operand: */
		/* checkQuickConstant:forInstruction: */
		genoperandoperandoperand(MoveMwrR, offset, FPReg, Extra1Reg);
		offset = oilVRegSpillTemp[callArgat(2, i)];

		/* begin MoveMw:r:R: */
		/* gen:quickConstant:operand:operand: */
		/* checkQuickConstant:forInstruction: */
