	/* #AddCq:R: #gen:quickConstant:operand: #checkQuickConstant:forInstruction: */
	genoperandoperand(AddCqR, BaseHeaderSize, Extra0Reg);

	/* Seed Extra3Reg from the first byte when at least 8 bytes remain */

