	genoperandoperand(AddCqR, BaseHeaderSize, TempReg);

	/* #MoveCq:R: #gen:quickConstant:operand: #checkQuickConstant:forInstruction: */
	genoperandoperand(MoveCqR, 0, ClassReg);

