	genoperandoperandoperand(MoveXbrRR, TempReg, Extra1Reg, ClassReg);

	/* #CmpCq:R: #gen:quickConstant:operand: #checkQuickConstant:forInstruction: */
	genoperandoperand(CmpCqR, 0, ClassReg);
	jumpByteHit = genConditionalBranchoperand(JumpNonZero, ((sqInt)0));

