	tagFalse = fetchClassTagOf(falseObject());
	if (((tag1 == tagTrue)
	 && (tag2 == tagFalse))
	 || ((tag1 == tagFalse)
	 && (tag2 == tagTrue))) {
		objMach = srcscratch(fieldAAt(irOffset), TempReg);

		/* #CmpCq:R: #gen:quickConstant:operand: #checkQuickConstant:forInstruction: */
		genoperandoperand(CmpCqR, trueObject(), objMach);
		jumpOK = genConditionalBranchoperand(JumpZero, ((sqInt)0));

		/* #CmpCq:R: #gen:quickConstant:operand: #checkQuickConstant:forInstruction: */
		genoperandoperand(CmpCqR, falseObject(), objMach);
		deoptsite(genConditionalBranchoperand(JumpNonZero, ((sqInt)0)), siteIndex);
		jmpTarget(jumpOK, genoperandoperand(Label, (labelCounter += 1), bytecodePC));
		return 0;
	}
	genClassTagOfinto(srcscratch(fieldAAt(irOffset), TempReg), SendNumArgsReg);

	/* #CmpCq:R: #gen:quickConstant:operand: #checkQuickConstant:forInstruction: */
	genoperandoperand(CmpCqR, tag1, SendNumArgsReg);
	jumpOK = genConditionalBranchoperand(JumpZero, ((sqInt)0));

	/* #CmpCq:R: #gen:quickConstant:operand: #checkQuickConstant:forInstruction: */
	genoperandoperand(CmpCqR, tag2, SendNumArgsReg);
	deoptsite(genConditionalBranchoperand(JumpNonZero, ((sqInt)0)), siteIndex);
	jmpTarget(jumpOK, genoperandoperand(Label, (labelCounter += 1), bytecodePC));
	return 0;
