	if (frameIndex < 0) {
		return 0;
	}
	if (((slotKind[rcvrReg]) == OilDescObject)
	 && (!(canInlineOnVObj(frameIndex)))) {
		materializeSlot(rcvrReg);
	}
	if (guard) {
		emitGuardOnclass(regForSlot(rcvrReg), classObj);
	}
	stabilizeIncomingSlot(rcvrReg);
