/*	For primitiveOilLastCompilation: 0 failure code, 1 IR size, 2 IR word, 3
	eager closures,
	 4 failed IR index, 5 sites, 6 frames, 7 spill slots, 8
	allocated regs, 9 metadata bytes, 11/12 Pass 1 IR, 13 Pass 2 stats.
 */

	/* OilInliningCompiler>>#oilDebugInfo:at: */
sqInt
oilDebugInfoat(sqInt what, sqInt index)
{
	if (!what) {
		return failureCode;
	}
	if (what == 1) {
		return irIndex;
	}
	if (what == 2) {
		return (((index >= 0) && (index <= (irIndex - 1)))
				? oilIRBuffer[index]
				: 0);
	}
	if (what == 3) {
		return (eagerClosures
				? 1
				: 0);
	}
	if (what == 4) {
		return oilFailIndex;
	}
	if (what == 5) {
		return numSites;
	}
	if (what == 6) {
		return numFrames;
	}
	if (what == 7) {
		return oilNumSpillTemps;
	}
	if (what == 8) {
		return oilNumAllocRegs;
	}
	if (what == 9) {
		return metadataObjectBytes();
	}
	if (what == 11) {
		return oilPass1Words;
	}
	if (what == 12) {
		return (((index >= 0) && (index <= (oilPass1Words - 1)))
				? oilIRBuffer1[index]
				: 0);
	}
	if (what == 13) {
		return pass2Statistics(index);
	}
	return 0;
}


