				mcpc = /* firstMappedPCFor: */
						((((cogMethod->cmType)) >= CMMethod)
					 && ((cogMethod->cpicHasMNUCaseOrCMIsFullBlock))
							? (((usqInt)cogMethod)) + cbNoSwitchEntryOffset
							: (((usqInt)cogMethod)) + cmNoCheckEntryOffset);
