		/* #AndCq:R: #gen:quickConstant:operand: #checkQuickConstant:forInstruction: */
		genoperandoperand(AndCqR, HashMultiplyMask, ReceiverResultReg);
		genConvertIntegerToSmallIntegerInReg(ReceiverResultReg);

		/* RetN: */
		genoperand(RetN, 0);
