		maybeHaltIfDebugPC();
		mergeWithFixupIfRequired((fixup = fixupAt(bytecodePC)));
		descriptor = loadBytesAndGetDescriptor(bytecodePC);
		nextOpcodeIndex = opcodeIndex;
